<?php
declare(strict_types=1);
namespace App\Services;
use App\Repositories\{FeeRepository,StudentRepository};
final class FeeService{
public function __construct(private readonly FeeRepository$fees,private readonly StudentRepository$students){}
public function ensureInvoice(array$student,int$institute,string$month,int$user):array{if($x=$this->fees->invoice((int)$student['id'],$month))return$x;$pdo=$this->fees->db()->connection();$pdo->beginTransaction();try{$items=$this->fees->scopedItems($institute,$month,$student['class_name'],$student['registration_no']);$tuition=$student['monthly_fee_override']!==null?(float)$student['monthly_fee_override']:(float)$student['monthly_tuition'];$lines=[['particular'=>'Monthly Tuition Fee','amount'=>$tuition]];foreach($items as$item)if(!in_array($item['item_key'],['monthly_tuition','previous_balance','discount'],true)&&(float)$item['amount']>0)$lines[]=['particular'=>$item['label'],'amount'=>(float)$item['amount']];$subtotal=array_sum(array_column($lines,'amount'));$value=(float)($student['discount_value']??$student['discount_in_fee']??0);$discount=($student['discount_type']??'percentage')==='fixed'?$value:round($subtotal*($value/100),2);$discount=min($subtotal,max(0,$discount));$previous=$this->fees->previousBalance((int)$student['id'],$month);$total=max(0,$subtotal-$discount+$previous);$now=date('Y-m-d H:i:s');$this->fees->createInvoice(['student_id'=>$student['id'],'fee_month'=>$month,'invoice_no'=>'INV-'.str_replace('-','',$month).'-'.$student['id'],'subtotal'=>$subtotal,'discount'=>$discount,'previous_balance'=>$previous,'total_amount'=>$total,'paid_amount'=>0,'remaining_amount'=>$total,'status'=>'unpaid','created_by'=>$user,'created_at'=>$now,'updated_at'=>$now],$lines);$pdo->commit();return$this->fees->invoice((int)$student['id'],$month)??throw new \RuntimeException('Invoice creation failed.');}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
public function collect(array$student,int$institute,string$month,float$amount,string$method,?string$reference,int$user,?string$paymentDate=null):int{$this->ensureInvoice($student,$institute,$month,$user);$pdo=$this->fees->db()->connection();$pdo->beginTransaction();try{$invoice=$this->fees->invoice((int)$student['id'],$month,true);if($amount<=0||$amount>(float)$invoice['remaining_amount'])throw new \InvalidArgumentException('Payment must be greater than zero and not exceed the remaining balance.');$payment=$this->fees->addPayment((int)$invoice['id'],(int)$student['id'],$amount,$method,$reference,$user);if($paymentDate!==null&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$paymentDate)&&$paymentDate<date('Y-m-d'))$this->fees->db()->query('UPDATE fee_payments SET payment_date=:d WHERE id=:id',['d'=>$paymentDate,'id'=>$payment]);$paid=(float)$invoice['paid_amount']+$amount;$this->fees->updateInvoice((int)$invoice['id'],$paid,max(0,(float)$invoice['total_amount']-$paid));$pdo->commit();(new \App\Services\Sms\SmsAutomation($this->fees->db()))->paymentReceived($payment);(new AccountAccess($this->fees->db()))->evaluateStudent((int)$student['id'],$institute);return$payment;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}

/** What the invoice for $month would contain, computed without creating it or carrying balances forward (eSkooly-style collection screen). */
public function preview(array$student,int$institute,string$month):array{$items=$this->fees->scopedItems($institute,$month,$student['class_name'],$student['registration_no']);$tuition=$student['monthly_fee_override']!==null?(float)$student['monthly_fee_override']:(float)$student['monthly_tuition'];$lines=[['particular'=>'Monthly Tuition Fee','amount'=>$tuition]];foreach($items as$item)if(!in_array($item['item_key'],['monthly_tuition','previous_balance','discount'],true))$lines[]=['particular'=>$item['label'],'amount'=>(float)$item['amount']];$subtotal=array_sum(array_column($lines,'amount'));$type=($student['discount_type']??'percentage')==='fixed'?'fixed':'percentage';$value=(float)($student['discount_value']??$student['discount_in_fee']??0);$discount=$type==='fixed'?$value:round($subtotal*($value/100),2);$discount=min($subtotal,max(0,$discount));$previous=$this->fees->outstandingBefore((int)$student['id'],$month);return['lines'=>$lines,'subtotal'=>$subtotal,'discount'=>$discount,'discount_type'=>$type,'discount_value'=>$value,'previous_balance'=>$previous,'total'=>max(0,$subtotal-$discount+$previous)];}
/**
 * Applies the amounts entered on the collection screen (eSkooly lets the cashier change every
 * line, the fine, the discount and the previous balance while collecting). Payments already
 * recorded are never touched: the new total may not drop below what has been paid, and the
 * remaining balance is re-derived as total - paid. Returns the before/after figures for the audit log.
 * @param list<array{particular:string,amount:float}> $lines
 */
public function adjustInvoice(int$invoiceId,array$lines,float$discount,float$fine,?float$previous=null):array{$pdo=$this->fees->db()->connection();$pdo->beginTransaction();try{$db=$this->fees->db();$inv=$db->query('SELECT * FROM fee_invoices WHERE id=:id FOR UPDATE',['id'=>$invoiceId])->fetch();if(!$inv)throw new \InvalidArgumentException('Invoice not found.');if($inv['voided_at'])throw new \InvalidArgumentException('This invoice is voided.');$paid=(float)$db->query('SELECT COALESCE(SUM(amount),0) FROM fee_payments WHERE fee_invoice_id=:i AND reversed_at IS NULL',['i'=>$invoiceId])->fetchColumn();$clean=[];foreach($lines as$l){$a=round((float)$l['amount'],2);$n=trim((string)$l['particular']);if($a<0)throw new \InvalidArgumentException('Fee amounts cannot be negative.');if($n!==''&&$a>0)$clean[]=['particular'=>mb_substr($n,0,120),'amount'=>$a];}if($fine<0||$discount<0||($previous!==null&&$previous<0))throw new \InvalidArgumentException('Fine, discount and previous balance cannot be negative.');if($fine>0)$clean[]=['particular'=>'Fine','amount'=>round($fine,2)];$prev=$previous===null?(float)$inv['previous_balance']:round($previous,2);$subtotal=array_sum(array_column($clean,'amount'));$discount=min($subtotal,round($discount,2));$total=max(0,$subtotal-$discount+$prev);if($total+0.001<$paid)throw new \InvalidArgumentException('The new total ('.number_format($total,2).') cannot be less than the '.number_format($paid,2).' already paid. Reverse or edit a payment first.');$remaining=max(0,round($total-$paid,2));$status=$remaining<=0?'paid':($paid>0?'partial':'unpaid');$before=['subtotal'=>$inv['subtotal'],'discount'=>$inv['discount'],'previous_balance'=>$inv['previous_balance'],'total_amount'=>$inv['total_amount'],'items'=>$this->fees->items($invoiceId)];$db->query('DELETE FROM fee_invoice_items WHERE fee_invoice_id=:i',['i'=>$invoiceId]);foreach($clean as$l)$db->query('INSERT INTO fee_invoice_items(fee_invoice_id,particular,amount,created_at) VALUES(:i,:p,:a,:c)',['i'=>$invoiceId,'p'=>$l['particular'],'a'=>$l['amount'],'c'=>date('Y-m-d H:i:s')]);$db->query('UPDATE fee_invoices SET subtotal=:s,discount=:d,previous_balance=:pb,total_amount=:t,paid_amount=:pd,remaining_amount=:r,status=:st,updated_at=:u WHERE id=:id',['s'=>$subtotal,'d'=>$discount,'pb'=>$prev,'t'=>$total,'pd'=>$paid,'r'=>$remaining,'st'=>$status,'u'=>date('Y-m-d H:i:s'),'id'=>$invoiceId]);$pdo->commit();return['before'=>$before,'after'=>['subtotal'=>$subtotal,'discount'=>$discount,'previous_balance'=>$prev,'total_amount'=>$total,'items'=>$clean]];}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
/** Kept for callers of the earlier API: adjusts an invoice that has no payments yet. */
public function adjustUnpaid(int$invoiceId,array$lines,float$discount,float$fine):void{if((int)$this->fees->db()->query('SELECT COUNT(*) FROM fee_payments WHERE fee_invoice_id=:i AND reversed_at IS NULL',['i'=>$invoiceId])->fetchColumn()>0)throw new \InvalidArgumentException('Particulars are locked once a payment has been recorded. Use Edit on the payment instead.');$this->adjustInvoice($invoiceId,$lines,$discount,$fine);}
}
